  <path d="M-17 1 V-5 Q-17 -7.5 -14 -7.5 L-9 -13.5 Q-8 -14.5 -6 -14.5 H4 Q6 -14.5 7 -13.5 L11.5 -8 L15 -7.5 Q17 -7 17 -4 V1 Z"/>
